  inv Mq mdq LKq Awq crq kq a -> xestk = e1 :: rr -> a = NB ->
  let ed := PEC.en_b en + 24 * (Z.of_nat (length rr) + 1) in
  msteps RSEGS (mst fxq Rq pcq (mrestrict (ahid Awq mdq) Mq)) (mst fx3 R3 r M3v) -> mem_grows (mrestrict (ahid Awq mdq) Mq) M3v ->
